HTML = '<!doctype html>\n<html lang="es">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>\n<title>Acta Clara</title>\n<meta name="claude:viewport-fit-sides" content="cover">\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Fraunces:opsz,wght@9..144,600&display=swap">\n<style>\n/* Layout: panel de casos a la izquierda, teléfono con chat a la derecha; una columna en móvil */\n:root{\n  --bg:#eef1ec; --panel:#ffffff; --ink:#1d2621; --muted:#5b6a61; --line:#d5ddd6;\n  --chat:#e7ddd2; --me:#d3f3c4; --bot:#ffffff; --accent:#0f6b4a; --warn:#a4400e; --ok:#1d7a3a; --sim:#6b5a9e;\n  --display:"Fraunces",Georgia,serif; --body:"Atkinson Hyperlegible",system-ui,sans-serif;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){\n  --bg:#121815; --panel:#1b231f; --ink:#e8eee9; --muted:#9fb0a6; --line:#2c3832;\n  --chat:#0e1411; --me:#1f4a33; --bot:#212b26; --accent:#5fd3a0; --warn:#f0a070; --ok:#7ed69a; --sim:#b8a6f0; color-scheme:dark}}\n:root[data-theme="dark"]{\n  --bg:#121815; --panel:#1b231f; --ink:#e8eee9; --muted:#9fb0a6; --line:#2c3832;\n  --chat:#0e1411; --me:#1f4a33; --bot:#212b26; --accent:#5fd3a0; --warn:#f0a070; --ok:#7ed69a; --sim:#b8a6f0; color-scheme:dark}\nbody{background:var(--bg);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.5}\n.wrap{max-width:1080px;margin:0 auto;padding-block:24px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;grid-template-columns:minmax(0,1fr) minmax(0,420px);gap:24px}\n@media (max-width:820px){.wrap{grid-template-columns:minmax(0,1fr)}}\nh1{font-family:var(--display);font-size:2rem;margin:0;text-wrap:balance}\n.lede{color:var(--muted);margin:6px 0 18px;max-width:60ch}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;display:flex;flex-direction:column;gap:12px}\n.label{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:700}\n.cases{display:grid;gap:8px}\n.case{all:unset;cursor:pointer;border:1px solid var(--line);border-radius:10px;padding:10px 12px;display:grid;gap:2px}\n.case:hover,.case:focus-visible{border-color:var(--accent);outline:2px solid transparent}\n.case:focus-visible{box-shadow:0 0 0 3px var(--accent)}\n.case b{font-size:1rem}.case span{font-size:.88rem;color:var(--muted)}\n.case[aria-pressed="true"]{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,transparent)}\n.src{font-size:.85rem;color:var(--muted)}.src a{color:var(--accent)}\n.legend{display:flex;flex-wrap:wrap;gap:8px;font-size:.82rem}\n.pill{border-radius:99px;padding:2px 10px;border:1px solid currentColor}\n.pill.real{color:var(--ok)}.pill.sim{color:var(--sim)}\n.phone{background:var(--chat);border:1px solid var(--line);border-radius:22px;display:flex;flex-direction:column;height:720px;max-height:85vh;overflow:hidden}\n.top{background:var(--accent);color:#fff;padding:12px 16px;font-weight:700;display:flex;justify-content:space-between;align-items:center}\n:root[data-theme="dark"] .top{color:#0b1a12}\n@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .top{color:#0b1a12}}\n.top small{font-weight:400;opacity:.85}\n.voz{all:unset;cursor:pointer;font-size:.85rem;font-weight:700;border:1.5px solid currentColor;border-radius:99px;padding:6px 12px}\n.voz:focus-visible{box-shadow:0 0 0 3px var(--ink)}\n.voz[aria-pressed="false"]{opacity:.7}\n.msgs{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:8px}\n.m{max-width:86%;padding:9px 12px;border-radius:12px;font-size:1.05rem;white-space:pre-wrap;word-wrap:break-word}\n.m.bot{background:var(--bot);align-self:flex-start;border-top-left-radius:2px}\n.m.me{background:var(--me);align-self:flex-end;border-top-right-radius:2px}\n.m.sim{border:1.5px dashed var(--sim)}\n.tag{display:block;font-size:.72rem;color:var(--sim);font-weight:700;margin-bottom:3px}\n.cite{display:block;font-size:.78rem;color:var(--muted);margin-top:6px}\n.doc{background:var(--bot);border-radius:10px;padding:8px 10px;font-size:.82rem;line-height:1.35;position:relative;overflow:hidden}\n.doc::after{content:"DOCUMENTO FICTICIO — SOLO DEMO";position:absolute;inset:0;display:grid;place-items:center;transform:rotate(-14deg);color:var(--warn);opacity:.22;font-weight:700;font-size:.9rem;pointer-events:none}\n.doc h4{margin:0 0 4px;font-size:.78rem;letter-spacing:.06em}\n.diff{color:var(--warn);font-weight:700}\n.bar{padding:10px;display:flex;gap:8px;border-top:1px solid var(--line);background:var(--panel)}\n.btn{all:unset;cursor:pointer;background:var(--accent);color:var(--panel);font-weight:700;border-radius:99px;padding:12px 18px;font-size:1.05rem;text-align:center;flex:1}\n.btn:focus-visible{box-shadow:0 0 0 3px var(--ink)}\n.btn[disabled]{opacity:.4;cursor:default}\n#mic[aria-pressed="true"]{background:var(--warn);color:var(--panel);border-color:var(--warn)}\n.nota{align-self:center;text-align:center;color:var(--muted);font-size:.9rem;max-width:34ch}\n.ghost{background:transparent;color:var(--accent);border:1px solid var(--accent);flex:0 0 auto}\n@media (prefers-reduced-motion:no-preference){.m{animation:in .25s ease}@keyframes in{from{opacity:.3;transform:translateY(4px)}}}\n</style>\n</head>\n<body>\n\n<div class="wrap">\n  <section>\n    <h1>Acta Clara</h1>\n    <p class="lede">Un asistente por WhatsApp que revisa el acta de nacimiento de una persona mayor, encuentra errores contra su INE y prepara la corrección ante el Registro Civil. Elija un caso y avance la conversación.</p>\n    <div class="panel">\n      <div class="label">Casos de demo</div>\n      <div class="cases" id="cases"></div>\n      <div class="legend"><span class="pill real">Validación de CURP y reglas en vivo</span></div>\n      <div class="label">Fuentes oficiales (consultadas 30/10/2026)</div>\n      <div class="src">\n        Plataforma Nacional del Registro Civil — <a href="https://www.miregistrocivil.gob.mx/" target="_blank" rel="noopener">miregistrocivil.gob.mx</a>: corrección de registro y aclaración de actas, resolución en hasta 5 días.<br>\n        RENAPO — estructura y dígito verificador de la CURP.<br>\n        INEGI, ENCIG 2025: 80% de pagos, trámites o solicitudes con barreras.\n      </div>\n      <p class="src">En este prototipo la lectura de fotos usa datos ya extraídos de documentos ficticios. La comparación de datos, la validación de CURP y la detección de errores corren de verdad en la página.</p>\n    </div>\n  </section>\n\n  <div class="phone" aria-label="Simulación de chat">\n    <div class="top"><span>Acta Clara<br><small>Asistente del Registro Civil</small></span><button type="button" id="voz" class="voz" aria-pressed="true">🔊 Voz activada</button></div>\n    <div class="msgs" id="msgs" aria-live="polite"></div>\n    <div class="bar"><button class="btn ghost" id="reset" type="button">Reiniciar</button><button class="btn ghost" id="mic" type="button" aria-pressed="false">🎤 Hablar</button><button class="btn" id="next" type="button">Enviar fotos</button></div>\n  </div>\n</div>\n\n<script>\nconst CASES=[\n {id:1,t:"Nombre con iniciales",d:"Acta “M.A.” vs INE “María Alejandra”",\n  acta:{nombre:"M.A.",ap1:"López",ap2:"García",fecha:"12/04/1953",sexo:"Mujer",ent:"Ciudad de México"},\n  ine:{nombre:"María Alejandra",ap1:"López",ap2:"García",curp:"LOGA530412MDFPRL08"}},\n {id:2,t:"Fecha invertida en CURP",d:"Acta 7 de marzo vs CURP 3 de julio",\n  acta:{nombre:"José Luis",ap1:"Hernández",ap2:"Ruiz",fecha:"07/03/1958",sexo:"Hombre",ent:"Puebla"},\n  ine:{nombre:"José Luis",ap1:"Hernández",ap2:"Ruiz",curp:"HERL580703HPLRZS00"}},\n {id:3,t:"Todo coincide",d:"El asistente no inventa errores",\n  acta:{nombre:"Guadalupe",ap1:"Ramírez",ap2:"Torres",fecha:"25/11/1960",sexo:"Mujer",ent:"Jalisco"},\n  ine:{nombre:"Guadalupe",ap1:"Ramírez",ap2:"Torres",curp:"RATG601125MJCMRD02"}},\n {id:4,t:"Foto borrosa",d:"Pide otra foto con instrucción clara",blur:true},\n {id:5,t:"Caso real: acta de la madre vs acta del hijo",d:"“María Elena” vs “Ma. Elena”",\n  acta:{nombre:"María Elena",ap1:"Sánchez",ap2:"Pérez",fecha:"18/09/1955",sexo:"Mujer",ent:"Ciudad de México"},\n  ine:{nombre:"María Elena",ap1:"Sánchez",ap2:"Pérez",curp:"SAPE550918MDFNRL09"},\n  hijo:{nombre:"Carlos Ruiz Sánchez",madre:"Ma. Elena Sánchez Pérez"}}\n];\nCASES.unshift(CASES.pop());CASES.forEach((c,i)=>c.id=i+1);\nconst ENT={AS:"Aguascalientes",BC:"Baja California",BS:"Baja California Sur",CC:"Campeche",CL:"Coahuila",CM:"Colima",CS:"Chiapas",CH:"Chihuahua",DF:"Ciudad de México",DG:"Durango",GT:"Guanajuato",GR:"Guerrero",HG:"Hidalgo",JC:"Jalisco",MC:"Estado de México",MN:"Michoacán",MS:"Morelos",NT:"Nayarit",NL:"Nuevo León",OC:"Oaxaca",PL:"Puebla",QT:"Querétaro",QR:"Quintana Roo",SP:"San Luis Potosí",SL:"Sinaloa",SR:"Sonora",TC:"Tabasco",TS:"Tamaulipas",TL:"Tlaxcala",VZ:"Veracruz",YN:"Yucatán",ZS:"Zacatecas",NE:"Nacido en el extranjero"};\nconst MESES=["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];\nconst norm=s=>s.normalize("NFD").replace(/[̀-ͯ]/g,"").toUpperCase().replace(/\\s+/g," ").trim();\nconst fechaTxt=(d,m,y)=>`${+d} de ${MESES[m-1]} de ${y}`;\n\nfunction curpValida(c){\n  const dic="0123456789ABCDEFGHIJKLMNÑOPQRSTUVWXYZ";\n  if(!/^[A-Z]{4}\\d{6}[HMX][A-Z]{5}[A-Z0-9]\\d$/.test(c))return false;\n  let s=0;for(let i=0;i<17;i++)s+=dic.indexOf(c[i])*(18-i);\n  return (10-s%10)%10===+c[17];\n}\nfunction analizar(cs){\n  const a=cs.acta,i=cs.ine,c=i.curp,errs=[];\n  if(!curpValida(c))errs.push({k:"curp",txt:"La CURP de su credencial no pasa la verificación. Puede tener un dígito equivocado."});\n  const nA=norm(a.nombre),nI=norm(i.nombre);\n  if(nA!==nI){\n    const ini=nA.replace(/\\./g," ").split(" ").filter(Boolean);\n    const esIni=ini.every(x=>x.length===1)&&ini.length===nI.split(" ").length&&ini.every((x,k)=>nI.split(" ")[k][0]===x);\n    errs.push({k:"nombre",txt:esIni?`En su acta su nombre está como “${a.nombre}”, solo con iniciales. En su credencial dice “${i.nombre}”.`:`Su nombre está escrito diferente: en el acta dice “${a.nombre}” y en su credencial “${i.nombre}”.`});\n  }\n  if(norm(a.ap1)!==norm(i.ap1)||norm(a.ap2)!==norm(i.ap2))errs.push({k:"apellidos",txt:`Sus apellidos no coinciden: “${a.ap1} ${a.ap2}” en el acta y “${i.ap1} ${i.ap2}” en la credencial.`});\n  const [d,m,y]=a.fecha.split("/").map(Number);\n  const cy=+c.slice(4,6),cm=+c.slice(6,8),cd=+c.slice(8,10),yy=y%100;\n  if(!(cy===yy&&cm===m&&cd===d)){\n    const inv=cy===yy&&cm===d&&cd===m;\n    errs.push({k:"fecha",txt:`Su fecha de nacimiento no coincide. El acta dice ${fechaTxt(d,m,y)} y su CURP dice ${fechaTxt(cd,cm,1900+cy)}.`+(inv?" Parece que el día y el mes se invirtieron al capturar la CURP.":"")});\n  }\n  const sx=c[10]==="H"?"Hombre":c[10]==="M"?"Mujer":"No binario";\n  if(sx!==a.sexo)errs.push({k:"sexo",txt:`El sexo en el acta (${a.sexo}) no coincide con la CURP (${sx}).`});\n  if(norm(ENT[c.slice(11,13)]||"")!==norm(a.ent))errs.push({k:"ent",txt:`El lugar de nacimiento no coincide: acta ${a.ent}, CURP ${ENT[c.slice(11,13)]||"desconocido"}.`});\n  if(cs.hijo){\n    const madreActa=norm(`${a.nombre} ${a.ap1} ${a.ap2}`),madreHijo=norm(cs.hijo.madre);\n    if(madreActa!==madreHijo)errs.push({k:"familia",txt:`En el acta de su hijo ${cs.hijo.nombre}, usted aparece como “${cs.hijo.madre}”. En su propia acta dice “${a.nombre} ${a.ap1} ${a.ap2}”.`});\n  }\n  return errs;\n}\n\nconst $=s=>document.querySelector(s),msgs=$("#msgs"),next=$("#next");\nlet cur=null,step=0;\nfunction say(who,html,opt={}){const el=document.createElement("div");el.className=`m ${who}`;el.innerHTML=html+(opt.cite?`<span class="cite">Fuente: ${opt.cite}</span>`:"");msgs.appendChild(el);msgs.scrollTop=msgs.scrollHeight;if(who==="bot")hablar(html);}\nlet vozOn=true;try{vozOn=localStorage.getItem("vozOn")!=="0"}catch(e){}\nfunction vozES(){const v=(window.speechSynthesis&&speechSynthesis.getVoices())||[];return v.find(x=>/es[-_]MX/i.test(x.lang))||v.find(x=>/^es/i.test(x.lang));}\nfunction hablar(html){\n  if(!vozOn||!window.speechSynthesis)return;\n  const t=html.replace(/<[^>]+>/g," ").replace(/[\\u{1F300}-\\u{1FAFF}•]/gu," ").replace(/\\bRC-(\\d+)-(\\d+)/,"R C $1 $2").replace(/\\s+/g," ").trim();\n  if(!t)return;\n  const u=new SpeechSynthesisUtterance(t);u.lang="es-MX";u.rate=0.92;const v=vozES();if(v)u.voice=v;\n  try{speechSynthesis.speak(u)}catch(e){}\n}\nfunction pintarVoz(){const b=document.querySelector("#voz");b.setAttribute("aria-pressed",vozOn);b.textContent=vozOn?"🔊 Voz activada":"🔇 Voz apagada";}\nfunction docHtml(title,rows,blur){return `<div class="doc" style="${blur?"filter:blur(3px)":""}"><h4>${title}</h4>${rows.map(r=>`<div>${r}</div>`).join("")}</div>`;}\nconst FUENTE="Plataforma Nacional del Registro Civil (miregistrocivil.gob.mx), consultado 30/10/2026";\n\nlet voz=null;\nfunction start(cs,meText){\n  cur=cs;step=0;msgs.innerHTML="";if(window.speechSynthesis)speechSynthesis.cancel();\n  document.querySelectorAll(".case").forEach(b=>b.setAttribute("aria-pressed",b.dataset.id==cs.id));\n  const intro=cs.hijo?{\n      me:"Hola, el abogado de la familia me dijo que mi nombre no está igual en el acta de mi hijo",\n      bot:"Hola, buenas tardes. Le ayudo a revisarlo.\\n\\nMándeme tres fotos, por favor: su acta de nacimiento, su INE y el acta de nacimiento de su hijo.",btn:"Enviar las 3 fotos"}\n    :/iniciales/i.test(cs.t)?{\n      me:"Hola, en mi pensión me dijeron que mi nombre no coincide con mi acta",\n      bot:"Hola, buenas tardes. Le ayudo a revisar su acta.\\n\\nMándeme una foto de su acta de nacimiento y otra de su INE, por favor.",btn:"Enviar fotos"}\n    :/fecha/i.test(cs.t)?{\n      me:"Hola, en el IMSS me dijeron que mi fecha de nacimiento no coincide con mi CURP",\n      bot:"Hola, buenas tardes. Le ayudo a revisar su fecha.\\n\\nMándeme una foto de su acta de nacimiento y otra de su INE, donde viene su CURP.",btn:"Enviar fotos"}\n    :cs.blur?{\n      me:"Hola, quiero revisar si mi acta tiene algún error",\n      bot:"Hola, buenas tardes. Con gusto la reviso.\\n\\nMándeme una foto de su acta de nacimiento y otra de su INE, por favor.",btn:"Enviar foto"}\n    :{\n      me:"Hola, en el banco me rechazaron un trámite y no sé si es por mi acta",\n      bot:"Hola, buenas tardes. Le ayudo a revisarlo.\\n\\nMándeme una foto de su acta de nacimiento y otra de su INE, por favor.",btn:"Enviar fotos"};\n  say("me",meText||intro.me);\n  say("bot",intro.bot);\n  next.textContent=intro.btn;next.disabled=false;\n}\nfunction advance(){\n  if(!cur){start(CASES[0]);return;}\n  const cs=cur;\n  if(step===0){\n    if(voz){say("me",voz);voz=null;}\n    if(cs.blur){\n      say("me",docHtml("ACTA DE NACIMIENTO (EJEMPLO)",["Nombre: Guadalupe","Apellidos: Ramírez Torres","Nacimiento: 25/11/1960"],true));\n      say("bot","No alcanzo a leer bien la foto del acta. ¿Me la puede tomar otra vez, cerca de una ventana con luz y sin que se mueva el teléfono?");\n      next.textContent="Reiniciar caso";step=99;return;\n    }\n    const a=cs.acta,i=cs.ine;\n    say("me",docHtml("ACTA DE NACIMIENTO (EJEMPLO)",[`Nombre: ${a.nombre}`,`Apellidos: ${a.ap1} ${a.ap2}`,`Nacimiento: ${a.fecha}`,`Sexo: ${a.sexo}`,`Entidad: ${a.ent}`]));\n    say("me",docHtml("CREDENCIAL DE IDENTIFICACIÓN (EJEMPLO)",[`Nombre: ${i.nombre} ${i.ap1} ${i.ap2}`,`CURP: ${i.curp}`]));\n    if(cs.hijo)say("me",docHtml("ACTA DE NACIMIENTO DEL HIJO (EJEMPLO)",[`Nombre: ${cs.hijo.nombre}`,`Nombre de la madre: <span class="diff">${cs.hijo.madre}</span>`]));\n    const errs=analizar(cs);cs._errs=errs;\n    if(!errs.length){\n      say("bot","Revisé sus documentos y coinciden. No encontré errores.\\n\\nSi le rechazaron un trámite, puede ser por otra razón. Le recomiendo preguntar en la oficina qué dato no coincide.");\n      next.textContent="Reiniciar caso";step=99;return;\n    }\n    say("bot","Encontré "+(errs.length===1?"un error":errs.length+" errores")+":\\n\\n"+errs.map(e=>"• "+e.txt).join("\\n")+"\\n\\nPor un punto o una letra, ante la ley puede parecer otra persona. Esto puede detener herencias, testamentos, seguros o su pensión.\\n\\nSí se puede corregir. ¿Quiere que yo haga el trámite por usted?",{cite:"validación de CURP (RENAPO) y comparación de datos"});\n    next.textContent="Sí, corríjalo";step=1;\n  }else if(step===1){\n    say("me",voz||"Sí, por favor");voz=null;\n    const k=cs._errs.map(e=>e.k);\n    const tipo=k.includes("fecha")&&!k.includes("nombre")?"corrección de datos de la CURP y del registro":"corrección de registro de acta";\n    say("bot",`Preparé su solicitud de ${tipo}:\\n\\n• Solicitante: ${cs.ine.nombre} ${cs.ine.ap1} ${cs.ine.ap2}\\n• CURP: ${cs.ine.curp}\\n• Qué se corrige: ${cs._errs.map(e=>e.k==="familia"?"nombre de la madre en el acta del hijo":e.k).join(", ")}\\n• Documentos: acta con el error, identificación oficial\\n\\nPara enviarla necesito confirmar que es usted. Tómese una selfie sosteniendo su INE.`,{cite:FUENTE});\n    next.textContent="Mandar selfie";step=2;\n  }else if(step===2){\n    if(voz){say("me",voz);voz=null;}\n    say("me","📷 Selfie con INE");\n    say("bot","Listo, confirmé su identidad.",{sim:true});\n    say("bot","Envié su solicitud al Registro Civil. Folio RC-2026-104827.\\n\\nEl plazo oficial para resolver es de hasta 5 días. Le aviso por aquí en cuanto quede.",{sim:true,cite:FUENTE});\n    next.textContent="Ver resultado (5 días después)";step=3;\n  }else if(step===3){\n    say("bot","Buenas noticias: su acta ya quedó corregida. Le mando su acta nueva en PDF. 📄\\n\\nYa puede usarla en su trámite.",{sim:true});\n    next.textContent="Reiniciar caso";step=99;\n  }else start(cs);\n}\nconst box=$("#cases");\nCASES.forEach(cs=>{const b=document.createElement("button");b.className="case";b.type="button";b.dataset.id=cs.id;b.innerHTML=`<b>${cs.id}. ${cs.t}</b><span>${cs.d}</span>`;b.onclick=()=>start(cs);box.appendChild(b);});\nnext.onclick=advance;\npintarVoz();if(window.speechSynthesis)speechSynthesis.onvoiceschanged=()=>{};\n$("#voz").onclick=()=>{vozOn=!vozOn;try{localStorage.setItem("vozOn",vozOn?"1":"0")}catch(e){}if(!vozOn&&window.speechSynthesis)speechSynthesis.cancel();pintarVoz();};$("#reset").onclick=()=>start(cur||CASES[0]);\nmsgs.innerHTML=\'<p style="margin:auto;text-align:center;color:var(--muted);font-size:1.05rem;max-width:28ch">Toque <b>Iniciar demo</b> o elija un caso para empezar la conversación con voz.</p>\';\nnext.textContent="Iniciar demo";\n\nfunction nota(t){const p=document.createElement("p");p.className="nota";p.textContent=t;msgs.appendChild(p);msgs.scrollTop=msgs.scrollHeight;}\nfunction elegirCaso(n){\n  if(/HIJ|ABOGAD|MADRE|MAMA/.test(n))return CASES[0];\n  if(/PENSION|INICIAL/.test(n))return CASES[1];\n  if(/IMSS|FECHA|CURP/.test(n))return CASES[2];\n  if(/BANCO/.test(n))return CASES[3];\n  return CASES[1];\n}\nfunction manejarVoz(t){\n  const n=norm(t);\n  if(!cur||step===99){start(elegirCaso(n),t);return;}\n  if(step===1&&/\\bNO\\b|DESPUES|AHORITA NO/.test(n)&&!/\\bSI\\b/.test(n)){\n    say("me",t);\n    say("bot","Entendido, no haré ningún cambio. Cuando quiera corregirlo, mándeme un mensaje o un audio.");\n    step=99;next.textContent="Reiniciar caso";return;\n  }\n  if(step===3){say("me",t);advance();return;}\n  voz=t;advance();\n}\nconst SR=window.SpeechRecognition||window.webkitSpeechRecognition;\nlet rec=null,escuchando=false;\nfunction pintarMic(){const b=$("#mic");b.setAttribute("aria-pressed",escuchando);b.textContent=escuchando?"● Escuchando…":"🎤 Hablar";}\n$("#mic").onclick=()=>{\n  if(!SR){nota("Este navegador no permite dictar. Ábralo en Chrome o Edge desde acta-clara.vercel.app.");return;}\n  if(escuchando){try{rec.stop()}catch(e){}return;}\n  if(window.speechSynthesis)speechSynthesis.cancel();\n  rec=new SR();rec.lang="es-MX";rec.interimResults=false;rec.maxAlternatives=1;\n  rec.onresult=e=>{const t=(e.results[0]&&e.results[0][0].transcript||"").trim();if(t)manejarVoz(t.charAt(0).toUpperCase()+t.slice(1));};\n  rec.onerror=e=>{if(e.error==="not-allowed"||e.error==="service-not-allowed")nota("No tengo permiso para usar el micrófono aquí. Ábralo en Chrome desde acta-clara.vercel.app y acepte el permiso.");else if(e.error==="no-speech")nota("No escuché nada. Toque Hablar e intente de nuevo.");};\n  rec.onend=()=>{escuchando=false;pintarMic();};\n  try{rec.start();escuchando=true;pintarMic();}catch(e){nota("No pude encender el micrófono. Intente de nuevo.");}\n};\n</script>\n</body>\n</html>\n'
